 ${open?`${customerResolutionsHTML()}<div class="grid"><div><section data-testid="menu-list" class="panel"><div class="split"><h2>เมนูจากครัว</h2><small>${s.menus.length} เมนู • ราคาจำลอง</small></div><div class="menu-grid">${s.menus.map((m,i)=>`<button data-testid="menu-item-${esc(m.id)}" data-action="select-menu" data-id="${esc(m.id)}" class="food" ${menuAvailable(m)?'':'disabled'}><span class="food-art">${m.image?`<img src="${esc(m.image)}" alt="${esc(m.name)}">`:`<span aria-hidden="true">${i===7?'◉':'♨'}</span>`}</span><span class="food-text"><strong>${esc(m.name)}</strong><span>${money(m.price)} · ${menuAvailable(m)?'สั่งได้':(!m.available?'ปิดขายโดยผู้จัดการ':'หมด')}</span></span></button>`).join('')||'<p>ยังไม่มีเมนู</p>'}</div></section>
 <section class="panel" aria-label="รายละเอียดจานที่เลือก"><h2>${m?esc(m.name):'เลือกเมนูเพื่อดูตัวเลือก'}</h2>${m?`${m.options.map(x=>`<label class="check"><input type="checkbox" data-testid="option-${esc(x.id)}" data-option="${esc(x.id)}" ${u.selectedOptions.includes(x.id)?'checked':''} ${optionAvailable(m,x)?'':'disabled'}>${esc(x.name)} +${money(x.price)} ${optionAvailable(m,x)?'':'· หมด / ปิดขาย'}</label>`).join('')||'<p class="muted">ไม่มีตัวเลือกเพิ่ม</p>'}<div class="split" style="margin-top:14px"><strong data-testid="item-total" class="amount">${money((cents(m.price)+selected.reduce((n,x)=>n+cents(x.price),0))/100)}</strong>${button('btn-add-item','เพิ่มลงตะกร้า','add-item',`class="primary" ${menuAvailable(m)?'':'disabled'}`)}</div>`:''}</section></div>
 <aside><section class="panel"><div class="split"><h2>ตะกร้าของคุณ</h2><span><span data-testid="cart-count">${cart.length}</span> จาน</span></div>${cart.length?`<ul class="list">${cart.map((i,n)=>`<li>${esc(i.name)}${i.options.length?' · '+i.options.map(x=>esc(x.name)).join(', '):''}<div class="split"><span>${money(i.total)}</span>${button('','นำออก','remove-cart',`data-id="${n}" aria-label="นำ ${esc(i.name)} ออกจากตะกร้า"`)}</div></li>`).join('')}</ul>`:'<p class="empty">เลือกจานโปรดจากเมนูได้เลย</p>'}<div class="split"><strong>รวม</strong><strong class="amount" data-testid="cart-total">${money(sum(cart))}</strong></div><p class="notice">เวลารอ (US-07): ยังประมาณไม่ได้ — seed ไม่มีค่าเฉลี่ย 7 วันและต่อเมนู; DI-07/A-05 ยังไม่ยืนยัน “พร้อมเสิร์ฟ”</p>${capacityNoticeHTML()}${button('btn-submit-order','ส่งออเดอร์เข้าครัว','submit-order','class="primary"')}<p class="message" role="status" data-testid="order-message">${esc(u.orderMessage)}</p></section>
 <section class="panel"><h2>ติดตามออเดอร์ล่าสุด</h2><div class="row"><span>ออเดอร์ <strong data-testid="order-id">${o?.id??''}</strong></span><strong data-testid="takeaway-id">${esc(o?.takeaway_id??'')}</strong></div><p><span class="status" data-testid="customer-order-status">${o?statuses[o.status]:''}</span></p><p class="muted">การแจ้งเตือนสถานะ จำลอง • อัปเดตในแท็บเดียว<br>ชื่อสถานะตาม fixture; DI-07/A-05 ยังไม่ยืนยันการแมป</p>${o?`<p>ยอดออเดอร์ ${money(o.total)} (snapshot เดิม)</p>${itemsHTML(o)}${adjustedHTML(o,'customer')}`:''}<h3>การชำระเงิน <span class="tag">จำลอง</span></h3><p data-testid="payment-status">${p?.state??'ยังไม่จ่าย'}</p><div class="row">${button('pay-cash','เลือกเงินสด','cash',!o||p?.state==='จ่ายแล้ว'?'disabled':'')}${button('pay-promptpay','PromptPay จำลอง','promptpay',!o||p?.state==='จ่ายแล้ว'?'disabled':'')}</div><p class="message" data-testid="cash-message">${esc(cashMessage(p))}</p>${p?.method==='promptpay'&&p.state!=='จ่ายแล้ว'?'<div class="qr" role="img" aria-label="ภาพแทน QR PromptPay จำลอง สแกนชำระเงินจริงไม่ได้"><span>QR จำลอง<br>ห้ามโอนเงินจริง</span></div><p>ค้างจ่ายจนหน้าร้านยืนยันสลิปจำลอง</p>':''}<small>เลือกวิธีจ่ายยังไม่เท่ากับหน้าร้านรับเงิน</small></section>
 <details class="panel"><summary>ออเดอร์ทั้งหมดในรอบนี้ (${sessionOrders().length})</summary>${sessionOrders().map(x=>`<article class="ticket">#${x.id} ${esc(x.takeaway_id||'โต๊ะ '+x.table_id)} · ${statuses[x.status]} · ${money(x.total)} · ${payment(x).state}${itemsHTML(x)}${adjustedHTML(x,'history')}${x.id!==o?.id&&payment(x).state!=='จ่ายแล้ว'?`<div class="row">${button('','เลือกเงินสด #'+x.id,'cash',`data-id="${x.id}"`)}${button('','เลือก PromptPay จำลอง #'+x.id,'promptpay',`data-id="${x.id}"`)}</div><p>${esc(cashMessage(payment(x)))}</p>${payment(x).method==='promptpay'?'<p class="notice">QR PromptPay จำลอง — ค้างจ่าย โปรดให้หน้าร้านยืนยัน ไม่มีการโอนเงินจริง</p>':''}`:''}</article>`).join('')||'<p>ยังไม่มีออเดอร์</p>'}</details></aside></div>`:`<div class="panel empty">เปิดเมนูเพื่อเริ่มเลือกอาหาร${session()?.state==='closed'?' • รอบโต๊ะเดิมปิดแล้ว ต้องเริ่ม session ใหม่':''}</div>`}</section>`;
}
function cashMessage(p){if(p?.state==='จ่ายแล้ว')return '';if(!s.promptpay)return 'PromptPay จำลองปิดบริการ กรุณาชำระเงินสดที่หน้าร้าน';if(p?.requested_at!==null&&p?.requested_at!==undefined&&s.now-p.requested_at>=600000)return 'ยังไม่ยืนยันถึง 10 นาที กรุณาชำระเงินสดที่หน้าร้าน';if(p?.method==='cash')return 'เลือกเงินสดแล้ว กรุณาชำระที่หน้าร้านและรอพนักงานกดรับเงิน';return '';}
function itemsHTML(o,context='read'){
 return '<ul class="list">'+orderItems(o).filter(i=>context!=='kitchen'||resolution(i).state!=='returned').map(i=>{
 const r=resolution(i),v=effectiveItem(i);
 return `<li data-item-id="${i.id}">${itemDescription(v)} — ${money(v.total)}
 ${r.state!=='queued'?`<span data-testid="item-state" class="status">${itemState(r)}</span>`:''}
 ${context==='kitchen'?button('btn-item-unavailable','ทำไม่ได้','item-unavailable',`data-id="${o.id}" data-item-id="${i.id}" ${r.state==='pending'||o.status===2?'disabled':''}`):''}
 ${context!=='kitchen'&&r.state!=='queued'?`<p class="muted">snapshot เดิม: ${itemDescription(i)} — ${money(i.total)}${r.state==='returned'?' · นำออกจากยอดและคิวที่ต้องทำแล้ว ไม่ใช่การโอนเงินคืน':''}</p>`:''}
 </li>`;
 }).join('')+'</ul>';
}
